static u8g2_t u8g2;

string system_status_l[] = {"Menu", "Scanner", "Controller", "Transmisor"};

const uint8_t *menu_options_img_l[] = {image_radar_bits, image_menuroller_bits, image_transmitter_bits};
const char *menu_options_l[] = {"scanner", "controller", "transmisor"};

const char *scanner_options_l[] = {"Hibrid node      H / E-NOW",
                                   "Reader node      R / LoRa",
                                   "Activator node   A / E-NOW",
                                   "Reader node      R / LoRa",
                                   "Hibrid node      H / LoRa"};
const char *saved_nodes_l[] = {"Node 1 - E-NOW", "Node Node2 - E-NOW", "Node3.1 - E-NOW"};
const char *controller_options_l[] = {"Rele 1           OFF",
                                      "Rele 2           ON",
                                      "Rele 3           ON",
                                      "Rele 4           ON",
                                      "Rele 5           ON",
                                      "Bomba de agua    OFF"};
const char *transmisor_options_l[] = {"scanner", "controller", "transmisor"};

static const char **menu_options_actual;

static int menu_length;
static int system_status;
static int menu_option;
static int scroll_offset;

extern QueueHandle_t button_queue;

void display_init(void)
{

    u8g2_esp32_hal_t hal = U8G2_ESP32_HAL_DEFAULT;
    hal.bus.i2c.sda = DISPLAY_SDA;
    hal.bus.i2c.scl = DISPLAY_SCL;

    u8g2_esp32_hal_init(hal);

    u8g2_Setup_ssd1306_i2c_128x64_noname_f(
        &u8g2,
        U8G2_R0,
        u8g2_esp32_i2c_byte_cb,
        u8g2_esp32_gpio_and_delay_cb);

    u8g2_SetI2CAddress(&u8g2, 0x78);
    u8g2_InitDisplay(&u8g2);
    u8g2_SetPowerSave(&u8g2, 0);
    u8g2_ClearBuffer(&u8g2);

    system_status = 0;
    menu_option = 0;
    menu_options_actual = menu_options_l;

    menu_length = sizeof(menu_options_l) / sizeof(menu_options_l[0]);
}

// task que actualiza el display
void task_display_draw(void *pvParameters)
{
    display_init();
    system_message recived_msg;

    while (1)
    {
        if (xQueueReceive(button_queue, &recived_msg, portMAX_DELAY))
        {
            printf("[Input] button %s pressed\n", recived_msg.text);

            switch (recived_msg.id)
            {
            case 0:
                menu_option--;
                break;
            case 1:
                menu_option++;
                break;
            case 2:

                if (system_status == 0)
                {
                    display_status_update(menu_option + 1);
                }
                else
                {
                    display_status_update(0);
                    // printf("[%s] Action: %s\n", menu_options_l[system_status], menu_options_actual[menu_option]);
                }
                break;
            default:
                break;
            }

            if (menu_option > menu_length - 1)
            {
                menu_option = 0;
            }
            else if (menu_option < 0)
            {
                menu_option = menu_length - 1;
            }

            if (system_status == 0)
            {
                display_show_menu();
            }
            else
            {
                display_show_scanner();
            }
        }
    }
}

int display_status_update(int option)
{
    system_status = option;

    switch (option)
    {
    case 1:
        menu_length = sizeof(scanner_options_l) / sizeof(scanner_options_l[0]);
        menu_options_actual = scanner_options_l;
        break;
    case 2:
        menu_length = sizeof(saved_nodes_l) / sizeof(saved_nodes_l[0]);
        menu_options_actual = saved_nodes_l;
        break;
    case 3:
        menu_length = sizeof(transmisor_options_l) / sizeof(transmisor_options_l[0]);
        menu_options_actual = transmisor_options_l;
        break;
    default:
        menu_length = sizeof(menu_options_l) / sizeof(menu_options_l[0]);
        menu_options_actual = menu_options_l;
        break;
    }

    menu_option = 0;
    scroll_offset = 0;
    return option;
}

void display_show_menu(void)
{
    u8g2_ClearBuffer(&u8g2);
    u8g2_SetBitmapMode(&u8g2, 1);
    u8g2_SetFontMode(&u8g2, 1);

    // battery
    u8g2_SetFont(&u8g2, u8g2_font_4x6_tr);
    u8g2_DrawStr(&u8g2, 5, 10, "75%");

    char title[30] = "| Select: ";
    strlcat(title, menu_options_l[menu_option], sizeof(title));

    // head data - station address - time
    u8g2_DrawStr(&u8g2, 19, 10, title);
    u8g2_DrawStr(&u8g2, 2, 38, "MAC: 00:1A:2B:3C:4D:5E");
    u8g2_SetFont(&u8g2, u8g2_font_timR14_tr);
    u8g2_DrawStr(&u8g2, 2, 30, "11:21 a.m.");

    // btm text
    u8g2_SetFont(&u8g2, u8g2_font_4x6_tr);
    u8g2_DrawStr(&u8g2, 5, 59, "3 Nodes sync | 2 - 1");

    int top_i = (menu_option + 2) % 3;
    int btm_i = (menu_option + 1) % 3;
    u8g2_DrawXBM(&u8g2, 105, -5, 21, 21, menu_options_img_l[top_i]);
    u8g2_DrawXBM(&u8g2, 105, 49, 21, 21, menu_options_img_l[btm_i]);
    u8g2_DrawXBM(&u8g2, 105, 22, 21, 21, menu_options_img_l[menu_option]);

    // layout
    u8g2_DrawXBM(&u8g2, 2, 2, 126, 61, image_layout_bits);
    u8g2_SendBuffer(&u8g2);
}

void display_show_scanner(void)
{
    u8g2_ClearBuffer(&u8g2);
    u8g2_SetBitmapMode(&u8g2, 1);
    u8g2_SetFontMode(&u8g2, 1);

    u8g2_DrawXBM(&u8g2, 2, 2, 124, 61, image_paint_7_bits);
    u8g2_SetFont(&u8g2, u8g2_font_4x6_tr);
    u8g2_DrawStr(&u8g2, 5, 10, "75%");
    if(system_status == 1) u8g2_DrawStr(&u8g2, 19, 10, "| Scanner Mode");
    if(system_status == 2) u8g2_DrawStr(&u8g2, 19, 10, "| Controller Mode");
    if(system_status == 3) u8g2_DrawStr(&u8g2, 19, 10, "| Transmisor Mode");
    // u8g2_DrawStr(&u8g2, 5, 59, "Finding nodes...");

    int max_menu_items = 5;

    if (menu_option < scroll_offset) // empuja el tope de arriba
    {
        scroll_offset = menu_option;
    }

    bool hidden_items = (scroll_offset + max_menu_items < menu_length); // calculamos si son > 5 items
    int view = hidden_items ? (max_menu_items - 1) : max_menu_items;    // si son mas, mostramos 4 / sino 5 o mas

    if (menu_option >= scroll_offset + view) // empuja el tope para abajo
    {
        scroll_offset = menu_option - view + 1;
    }

    for (int i = 0; i < view; i++)
    {
        int index = i + scroll_offset;
        if (index >= menu_length)
        {
            break;
        };

        int y_pos = 21 + (i * 7);
        char buffer_linea[40];

        if (index == menu_option)
        {
            snprintf(buffer_linea, sizeof(buffer_linea), "> %s", menu_options_actual[index]);

            u8g2_SetDrawColor(&u8g2, 2);
            u8g2_DrawBox(&u8g2, 0, y_pos - 7, 128, 9);
        }
        else
        {
            snprintf(buffer_linea, sizeof(buffer_linea), "  %s", menu_options_actual[index]);
        }

        u8g2_DrawStr(&u8g2, 5, y_pos, buffer_linea);
    }

    if (hidden_items)
    {
        int y_pos_puntos = 21 + (4 * 7);
        u8g2_DrawStr(&u8g2, 5, y_pos_puntos, "  ...");
    }

    u8g2_SendBuffer(&u8g2);
}

void display_update(void)
{
    u8g2_SendBuffer(&u8g2);
}